INSERT INTO planets (id, name, name_cn, distance_from_sun, orbital_period, rotation_period, radius, mass, color, description, moons, orbital_inclination, axial_tilt, eccentricity, mean_anomaly_j2000, perihelion_longitude) VALUES
(1, 'Mercury', '水星', 0.39, 87.969, 58.6, 2439.7, 0.33, '#8C7853', '水星是太阳系中最小的行星，也是距离太阳最近的行星。表面温度变化极大，白天可达430°C，夜晚降至-180°C。', 0, 7, 0.03, 0.2056, 174.796, 77.45),
(2, 'Venus', '金星', 0.72, 224.701, -243, 6051.8, 4.87, '#FFC649', '金星是太阳系中最热的行星，表面温度高达465°C。它的自转方向与其他行星相反，且自转速度极慢。大气层主要由二氧化碳组成。', 0, 3.39, 177.4, 0.0068, 50.115, 131.53),
(3, 'Earth', '地球', 1, 365.256, 1, 6371, 5.97, '#4169E1', '地球是太阳系中唯一已知存在生命的行星。拥有液态水、适宜的温度和富含氧气的大气层。地球的自转轴倾斜23.5度，形成了四季变化。', 1, 0, 23.44, 0.0167, 357.529, 102.94),
(4, 'Mars', '火星', 1.52, 686.98, 1.03, 3389.5, 0.642, '#CD5C5C', '火星被称为"红色星球"，因其表面富含氧化铁。火星拥有太阳系最高的山峰（奥林帕斯山，高约22公里）和最大的峡谷。', 2, 1.85, 25.19, 0.0934, 19.373, 336.04),
(5, 'Jupiter', '木星', 5.2, 4332.59, 0.41, 69911, 1898, '#DAA520', '木星是太阳系最大的行星，质量是其他所有行星总和的2.5倍。著名的大红斑是一个持续了至少350年的巨型风暴。木星拥有强大的磁场。', 79, 1.31, 3.13, 0.0489, 120.537, 273.867),
(6, 'Saturn', '土星', 9.54, 10759.2, 0.45, 58232, 568, '#F4A460', '土星以其壮观的行星环系统而闻名，环主要由冰粒和岩石碎片组成。土星的密度很低，甚至能漂浮在水上。', 82, 2.49, 26.73, 0.0565, 70.685, 339.392),
(7, 'Uranus', '天王星', 19.19, 30688.5, -0.72, 25362, 86.8, '#4FD0E0', '天王星的自转轴几乎平躺在轨道平面上，倾斜角度达98度。这使得它的季节变化极为极端，每个季节持续约21年。大气层呈蓝绿色。', 27, 0.77, 97.77, 0.0457, 217.057, 96.998),
(8, 'Neptune', '海王星', 30.07, 60182, 0.67, 24622, 102, '#4169E1', '海王星是太阳系距离太阳最远的行星，也是风速最快的行星，风速可达2100km/h。其深蓝色外观来自大气层中的甲烷。', 14, 1.77, 28.32, 0.0113, 31.161, 273.187),
(9, 'Pluto', '冥王星', 39.48, 90560, -6.387, 1188.3, 0.013, '#C2B280', '冥王星是柯伊伯带中已知最大的矮行星。2006年被国际天文学联合会重新分类为矮行星。它有一颗大卫星冥卫一（卡戎），两者几乎构成双星系统。表面主要由氮冰、甲烷冰和一氧化碳冰覆盖。', 5, 17.16, 122.53, 0.2488, 14.53, 224.07);
